WITH ranked AS (SELECT id, location, budget FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY location ORDER BY budget, id) AS dedup_rank FROM departments) t WHERE dedup_rank = 1) SELECT CASE WHEN budget >= 4445000 THEN 'HIGH' ELSE 'LOW' END AS budget_tier, location, SORT_ARRAY(COLLECT_SET(location)) AS location_list, SORT_ARRAY(COLLECT_SET(location)) AS location_list_2, COUNT_IF(location = 'New York') AS new_york_events, PERCENTILE_APPROX(budget, 0.95) AS budget_p95, ROUND(AVG(budget), 2) AS avg_budget, DENSE_RANK() OVER (PARTITION BY CASE WHEN budget >= 4445000 THEN 'HIGH' ELSE 'LOW' END ORDER BY ROUND(AVG(budget), 2) DESC) AS avg_budget_dense_rank FROM ranked GROUP BY 1, 2 HAVING COUNT_IF(location = 'New York') < 1000 ORDER BY avg_budget NULLS LAST
